CASE
  WHEN task_row.task_type = #{filter.standardTaskType}
   AND task_row.mode = #{filter.normalLinkMode}
    THEN standard_group_setting.group_name
  ELSE task_row.group_name
END

task_row.deleted_at IS NULL

AND NOT (task_row.task_type = #{filter.hiddenTaskType}
  AND task_row.status = #{filter.hiddenStatus})
AND task_row.id = #{filter.id}

  AND (task_row.task_name LIKE CONCAT('%', #{filter.keyword}, '%')
    OR ()
      LIKE CONCAT('%', #{filter.keyword}, '%'))

AND task_row.status = #{filter.status}
AND task_row.task_type = #{filter.taskType}

  AND task_row.group_source = #{filter.groupSource}


  AND task_row.operator_name LIKE CONCAT('%', #{filter.operator}, '%')

mapper.update:
UPDATE pull_task
SET status = #{toStatus},
    version = version + 1,
    updated_at = #{now}
    , started_at = #{startedAt}
    , finished_at = #{finishedAt}
WHERE id = #{id}
  AND deleted_at IS NULL
  AND status = #{fromStatus}
  AND version = #{expectedVersion}

UPDATE pull_task
SET status = #{transition.targetStatus},
    blocking_reason = #{transition.blockingReason},
    version = version + 1,
    updated_at = #{transition.now}

      , started_at = COALESCE(started_at, #{transition.startedAt})


      , finished_at = #{transition.finishedAt}

WHERE id = #{transition.taskId}
  AND deleted_at IS NULL
  AND status = #{transition.expectedStatus}
  AND version = #{transition.expectedVersion}

