mapper.select:
SELECT id, tenant_id, task_type, task_name, mode, status, version,
       group_count, expected_pull_count, created_by, remark,
       created_at, updated_at
FROM pull_task
WHERE deleted_at IS NULL
  AND task_type = #{taskType}
  AND status = #{status}
  AND created_by = #{createdBy}
ORDER BY id DESC
LIMIT 1

mapper.update:
UPDATE pull_task
SET status = #{row.status},
    version = version + 1,
    task_name = #{row.taskName},
    remark = #{row.remark},
    group_count = #{row.groupCount},
    expected_pull_count = #{row.expectedPullCount},
    updated_at = #{now}
WHERE id = #{row.id}
  AND deleted_at IS NULL
  AND task_type = #{expectedTaskType}
  AND status = #{expectedStatus}
  AND version = #{expectedVersion}

UPDATE pull_task
SET version = version + 1,
    updated_at = #{claim.now}
WHERE id = #{claim.candidate.taskId}
  AND deleted_at IS NULL
  AND task_type = #{claim.parent.taskType}
  AND mode = #{claim.parent.taskMode}
  AND status = #{claim.parent.taskStatus}
  AND version = #{claim.parent.expectedVersion}
  AND EXISTS (
    SELECT 1
    FROM pull_task_group_execution candidate_execution
    WHERE candidate_execution.tenant_id = pull_task.tenant_id
      AND candidate_execution.task_id = pull_task.id
      AND candidate_execution.id = #{claim.candidate.executionId}
      AND candidate_execution.execution_status = #{claim.candidate.executionStatus}
      AND candidate_execution.stage = #{claim.candidate.executionStage}
      AND candidate_execution.version = #{claim.candidate.lease.expectedVersion}
      AND candidate_execution.lock_owner = #{claim.candidate.lease.lockOwner}
      AND candidate_execution.lock_expires_at > #{claim.now}
  )
  AND (
    SELECT COUNT(*)
    FROM pull_task_group_execution running_execution
    WHERE running_execution.tenant_id = pull_task.tenant_id
      AND running_execution.task_id = pull_task.id
      AND running_execution.id != #{claim.candidate.executionId}
      AND running_execution.execution_status = #{claim.policy.runningExecutionStatus}
  ) < #{claim.policy.concurrentLimit}
